// План: specs/deals.md, блок 4. Кейсы: .qa/tests/deals/DEAL-009, DEAL-010. Тикет #a316a1 (13bd4ffea1e3b7adcba316a1).
// Несколько ролей: клиент 0500000004 («יונתן לוי») платит, נותן שירות 0500000005 («שירה כהן») получает и оценивает клиента.
// Нужна своя сделка в נאמנות: QA_RATING_ESCROW_DEAL_ID=<id> или QA_ALLOW_DEPOSIT=1 (создаст QA-AUTO-דירוג …).
// Освобождение переводит тестовые деньги client → provider, оценка остаётся у клиента → @data, не @prod-safe.
// Селекторы звёзд не сверены в живом браузере — подтвердить при первом /qa-regress (класс «ошибка теста», не баг).
import { test, expect } from '../../fixtures';
import type { Page, Locator } from '@playwright/test';
import { getEscrowDeal, waitWithReload, CLIENT_NAME } from '../disputes/helpers';

test.describe.configure({ mode: 'serial', retries: 0 });

const MENU = 'פעולות נוספות';
const RATE_CLIENT = 'דירוג הלקוח';
const RATE_PROVIDER = 'דירוג נותן השירות';
const QUESTION = 'איך הייתה העבודה עם הלקוח?';
const SEND = 'שליחת דירוג';
const SKIP = 'דלג';
const TOO_LONG = 'הביקורת יכולה להכיל עד 500 תווים';
const NOT_RATED = 'לקוח חדש · עדיין לא דורג';
const RATING_LINE = /\d\.\d · (דירוג אחד|[\d,]+ דירוגים)/;

let dealId = '';

async function openMenu(page: Page) {
  await page.goto(`/deals/${dealId}`);
  await page.getByRole('button', { name: MENU }).click();
}

async function openRatingForm(provider: Page) {
  await openMenu(provider);
  await provider.getByText(RATE_CLIENT, { exact: true }).last().click();
  await expect(provider.getByText(QUESTION)).toBeVisible();
}

/** Пять звёзд внутри карточки с вопросом «איך הייתה העבודה עם הלקוח?». Порядок DOM: 1…5. */
async function stars(page: Page): Promise<Locator> {
  const card = page.locator('div').filter({ has: page.getByText(QUESTION, { exact: true }) }).last();
  const buttons = card.getByRole('button');
  if ((await buttons.count()) >= 5) return buttons;
  return card.locator('svg');
}

const review = (page: Page) => page.getByRole('textbox').last();
const sendButton = (page: Page) => page.getByRole('button', { name: SEND });

test.describe('דירוג כפול — נותן שירות מדרג את הלקוח', () => {
  test('לפני שחרור הכסף אין "דירוג הלקוח" @iphone @data #a316a1', async ({ asUser }) => {
    const client = await asUser('client');
    const provider = await asUser('provider');
    ({ id: dealId } = await getEscrowDeal(client, provider, 'RATING'));

    await provider.goto(`/deals/${dealId}`);
    await expect(provider.getByText('הכסף שמור בנאמנות').first()).toBeVisible();
    await provider.getByRole('button', { name: MENU }).click();
    await expect(provider.getByText('ביטול עסקה', { exact: true }).last(), 'меню открылось').toBeVisible();
    await expect(provider.getByText(RATE_CLIENT, { exact: true }), 'до освобождения оценки клиента нет (F-53 AC4)').toHaveCount(0);
    await provider.keyboard.press('Escape');
  });

  test('אחרי שחרור: טופס "דירוג הלקוח" — כוכבים חובה, ביקורת עד 500, "דלג" @iphone @data #a316a1', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const client = await asUser('client');
    const provider = await asUser('provider');

    // Освобождение денег (как REL-002…004): поставщик просит, клиент подтверждает.
    await provider.goto(`/deals/${dealId}`);
    await provider.getByRole('button', { name: 'בקשה לקבלת הכסף' }).click();
    await provider.getByRole('checkbox').last().click();
    await provider.getByRole('button', { name: 'שליחת בקשה' }).last().click();
    await expect(provider.getByText('ממתין לאישור הלקוח', { exact: true }).first()).toBeVisible();

    await client.goto(`/deals/${dealId}`);
    await waitWithReload(client, client.getByRole('button', { name: 'אישור קבלת השירות ותשלום' }));
    await client.getByRole('button', { name: 'אישור קבלת השירות ותשלום' }).last().click();
    await client.getByRole('checkbox').last().click();
    await client.getByRole('button', { name: 'אישור קבלת השירות ותשלום' }).last().click();

    await provider.goto(`/deals/${dealId}`);
    await waitWithReload(provider, provider.getByRole('button', { name: MENU }));
    await openRatingForm(provider);

    // Экран (F-53 AC1–3).
    await expect(provider.getByText(RATE_CLIENT, { exact: true }).first()).toBeVisible();
    await expect(provider.getByText(CLIENT_NAME, { exact: true }).first()).toBeVisible();
    await expect(provider.getByText('הוספת ביקורת', { exact: true })).toBeVisible();
    await expect(provider.getByRole('button', { name: SKIP })).toBeVisible();
    expect(await (await stars(provider)).count(), '5 звёзд').toBeGreaterThanOrEqual(5);

    // Звёзды обязательны.
    await expect(sendButton(provider), 'без звёзд отправка неактивна').toBeDisabled();

    // 501 символ — ошибка и кнопка неактивна, даже со звёздами.
    await (await stars(provider)).nth(3).click();
    await review(provider).fill('ב'.repeat(501));
    await expect(provider.getByText(TOO_LONG)).toBeVisible();
    await expect(sendButton(provider), '501 символ — нельзя отправить').toBeDisabled();

    // Ровно 500 — можно.
    await review(provider).fill('ב'.repeat(500));
    await expect(provider.getByText(TOO_LONG)).toHaveCount(0);
    await expect(sendButton(provider), '500 символов + звёзды — можно отправить').toBeEnabled();

    // «דלג» не тратит оценку.
    await provider.getByRole('button', { name: SKIP }).click();
    await openMenu(provider);
    await expect(provider.getByText(RATE_CLIENT, { exact: true }).last(), 'после «דלג» оценка доступна').toBeVisible();
    await provider.keyboard.press('Escape');
  });

  test('שליחת דירוג — פעם אחת בלבד; דירוג הלקוח ב"הצדדים בעסקה"; הלקוח עדיין מדרג את נותן השירות @iphone @data #a316a1', async ({ asUser }) => {
    test.skip(!dealId, 'нет сделки из предыдущего шага');
    const client = await asUser('client');
    const provider = await asUser('provider');

    await openRatingForm(provider);
    await (await stars(provider)).nth(3).click();
    await review(provider).fill('QA-AUTO: דירוג לקוח אוטומטי');
    await expect(sendButton(provider)).toBeEnabled();
    await sendButton(provider).click();
    await expect(provider.getByText(QUESTION)).toHaveCount(0);

    // Один раз на сделку.
    await provider.goto(`/deals/${dealId}`);
    await expect(provider.getByText('הצדדים בעסקה').first()).toBeVisible();
    const menu = provider.getByRole('button', { name: MENU });
    if (await menu.count()) {
      await menu.click();
      await expect(provider.getByText(RATE_CLIENT, { exact: true }), 'повторно оценить нельзя').toHaveCount(0);
      await provider.keyboard.press('Escape');
    }

    // Рейтинг клиента в «הצדדים בעסקה».
    await provider.goto(`/deals/${dealId}`);
    await expect(provider.getByText(RATING_LINE).first(), 'средний и число оценок клиента').toBeVisible();
    await expect(provider.getByText(NOT_RATED), 'клиент уже оценён').toHaveCount(0);

    // Клиент по-прежнему оценивает נותן שירות (С1, #152179).
    await client.goto(`/deals/${dealId}`);
    await client.getByRole('button', { name: MENU }).click();
    await expect(client.getByText(RATE_PROVIDER, { exact: true })).toBeVisible();
    await client.keyboard.press('Escape');
  });
});
